from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI()

class Item(BaseModel):
    name: str
    price: float

@app.post('/items')
def create_item(item: Item):
    return {'item': item.dict(), 'status': 'created'}

from fastapi import FastAPI
import json

app = FastAPI()

# Basit model simülasyonu
model_data = {'type': 'linear', 'weights': [0.5, 0.3]}

@app.post('/predict')
def predict(features: dict):
    result = sum(w * f for w, f in zip(model_data['weights'], features.get('values', [0, 0])))
    return {'prediction': result}

@app.get('/health')
def health():
    return {'status': 'healthy', 'model': model_data['type']}

